# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")

def gaps_for(*texts):
    spans = [parse_span(text) for text in texts]
    return find_gaps(spans, OPEN)

class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        self.assertEqual(
            gaps_for("09:00-12:00", "13:00-17:00"),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            gaps_for("10:00-16:30"),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:30-17:00 (30 min)",
            ],
        )

    def test_nobody_working(self):
        self.assertEqual(
            gaps_for(), ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage(self):
        self.assertEqual(
            gaps_for("09:00-13:00", "13:00-17:00"), []
        )

    def test_overlaps_are_merged(self):
        self.assertEqual(
            gaps_for("09:00-14:00", "11:00-15:00"),
            ["gap 15:00-17:00 (120 min)"],
        )

    def test_unsorted_input(self):
        self.assertEqual(
            gaps_for("14:00-17:00", "09:00-12:00"),
            ["gap 12:00-14:00 (120 min)"],
        )

    def test_starts_before_opening(self):
        with self.assertRaises(ValueError):
            gaps_for("08:00-12:00")

    def test_ends_after_opening(self):
        with self.assertRaises(ValueError):
            gaps_for("12:00-18:00")
